-- Idempotent, never duplicates: rows land in a staging table and are copied into qto_cache ONLY if
-- qto_cache is empty (a DB that already carries its own costs is left exactly as it is).
CREATE TABLE IF NOT EXISTS qto_cache (
    ifc_class TEXT NOT NULL, storey TEXT NOT NULL, discipline TEXT NOT NULL,
    qty REAL NOT NULL, uom TEXT NOT NULL, element_count INTEGER NOT NULL,
    material_cost REAL, labour_cost REAL, equipment_cost REAL,
    rate_template TEXT, computed_at TEXT,
    PRIMARY KEY (ifc_class, storey, discipline, rate_template)
  );
DROP TABLE IF EXISTS _qto_patch;
CREATE TABLE _qto_patch AS SELECT * FROM qto_cache WHERE 0;
